#include <Servo.h>

Servo servoTeplica; // Форточка теплицы (пин 11)
Servo servoParnik;  // Парник (пин 10)

void setup() {
  // Реле только ОДНО (на пине 3)
  pinMode(3, OUTPUT); 
  digitalWrite(3, LOW); // Выключаем при старте

  Serial.begin(9600);

  servoTeplica.attach(11); 
  servoParnik.attach(10);  
}

void loop() {
  if (Serial.available()) {
    char val = Serial.read();

    // УПРАВЛЕНИЕ ТЕПЛИЦЕЙ (Обе команды идут на пин 3)
    if (val == 'a') { digitalWrite(3, HIGH); } // Полив ВКЛ
    if (val == 'b') { digitalWrite(3, LOW); }  // Полив ВЫКЛ
    if (val == 'c') { digitalWrite(3, HIGH); } // Обогрев ВКЛ
    if (val == 'd') { digitalWrite(3, LOW); }  // Обогрев ВЫКЛ

    // Сервоприводы
    if (val == 'e') { servoTeplica.write(0); }   // Форточка ОТКРЫТА
    if (val == 'f') { servoTeplica.write(180); } // Форточка ЗАКРЫТА

    if (val == 'g') { servoParnik.write(0); }   // Парник ОТКРЫТ
    if (val == 'h') { servoParnik.write(180); } // Парник ЗАКРЫТ
  }
}
